arguments.content:
/* Grepo design tokens v1.0 — imported from PRD design/tokens.css */
:root {
  /* Core palette */
  --grepo-canvas:        #FAFBF7;
  --grepo-surface:       #FFFFFF;
  --grepo-surface-muted: #F3F5F0;
  --grepo-ink:           #172019;
  --grepo-text-secondary:#526057;
  --grepo-line:          #DFE5DA;
  --grepo-lime:          #C6F84A;
  --grepo-lemon:         #F2F85B;
  --grepo-green-strong:  #28643A;
  --grepo-caution:       #7A5200;
  --grepo-error:         #A33232;
  --grepo-focus:         #365A21;

  /* Typography */
  --grepo-font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --grepo-font-mono: ui-monospace, "Cascadia Code", "Liberation Mono", Consolas, monospace;

  /* Spacing (8px base) */
  --grepo-space-1:  4px;
  --grepo-space-2:  8px;
  --grepo-space-3: 12px;
  --grepo-space-4: 16px;
  --grepo-space-6: 24px;
  --grepo-space-8: 32px;

  /* Shape */
  --grepo-radius-control: 12px;
  --grepo-radius-card:    20px;
  --grepo-shadow-card:    0 6px 24px rgba(23,32,25,.055);

  /* Motion */
  --grepo-duration-fast:   120ms;
  --grepo-duration-normal: 180ms;

  /* Layout targets (derived from PRD §25.2) */
  --grepo-topbar-h:     72px;
  --grepo-nav-w:        224px;
  --grepo-tree-w:       260px;
  --grepo-panel-w:      340px;
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --grepo-duration-fast:   0ms;
    --grepo-duration-normal: 0ms;
  }
}
